def solve(a):
    n = len(a)
    odd_idx = [i for i, x in enumerate(a) if x % 2 == 1]
    even_idx = [i for i, x in enumerate(a) if x % 2 == 0]

    def can_swap(i, j):
        return (i in odd_idx and j in odd_idx) or (i in even_idx and j in even_idx)

    def is_sorted(a):
        return all(a[i] <= a[i+1] for i in range(n-1))

    def sort_parity(a):
        parity = [i % 2 for i in a]
        a.sort(key=lambda x: (parity[x-1], x))

    for i, j in itertools.combinations(range(n), 2):
        if can_swap(i, j) and not is_sorted(a):
            a[i], a[j] = a[j], a[i]
            sort_parity(a)
            if is_sorted(a):
                return "YES"

    return "NO"

