 def solve(n, a):
    # Check if the array is already good
    if all(x >= 0 for x in a) and len(set(a)) == 1:
        return 0

    # Find the first element that is not equal to its opposite
    first_bad_index = None
    for i in range(n):
        if a[i] != -a[i]:
            first_bad_index = i
            break

    # If no bad element found, the array is already good
    if first_bad_index is None:
        return 0

    # Find the first element that can be changed to make the array good
    first_good_index = None
    for i in range(first_bad_index, n):
        if a[i] != -a[i]:
            first_good_index = i
            break

    # If no good element found, the array cannot be made good
    if first_good_index is None:
        return -1

    # Make the first good element negative
    a[first_good_index] *= -1

    # Recursively call the function on the rest of the array
    return 1 + solve(n - first_good_index - 1, a[first_good_index + 1:])


