    else:
        # If the destination is not on the same diagonal, the minimum number of moves is the sum of the absolute differences between a and c, and b and d.
        min_moves = abs(a - c) + abs(b - d)

    # If the minimum number of moves is 1, it is possible to reach the destination in 1 move.
    if min_moves == 1:
        return 1
    # If the minimum number of moves is greater than 1, it is possible to reach the destination in more than 1 move.
    else:
