import math

def solve(n, m, x1, y1, x2, y2):
    # Check if the end point is within the bounds of the maze
    if x1 == x2 and 1 <= y1 <= m and y2 <= m:
        return math.inf
    if y1 == y2 and 1 <= x1 <= n and x2 <= n:
        return math.inf

    # Initialize the dp array with 0s
    dp = [[0] * (m+1) for _ in range(n+1)]

    # Initialize the dp array with the obstacles
    for i in range(1, n+1):
        for j in range(1, m+1):
            if i == x1 and j == y1 or i == x2 and j == y2:
                dp[i][j] = math.inf

    # Fill in the dp array
    for i in range(1, n+1):
        for j in range(1, m+1):
            if dp[i][j] != 0:
                continue
            for k in range(1, 4):
                di = i + (-1) ** k
                dj = j + (-2) ** k
                if 1 <= di <= n and 1 <= dj <= m and dp[di][dj] != math.inf:
                    dp[i][j] = max(dp[i][j], dp[di][dj] + 1)
    return dp[x2][y2]

