vector<int> solve(int n, int s, int r) {
    vector<int> a(n);

    // find the maximum number that can be rolled with n - 1 dice
    int max_roll = r / (n - 1);

    // find the minimum number that is still possible to roll with n - 1 dice
    int min_roll = max(1, r % (n - 1) + 1);

    // find the range of possible values for the maximum number
    int range = (max_roll - min_roll) + 1;

    // fill the vector with the possible values for the maximum number
    generate(a.begin(), a.end(), [=, &min_roll, &range]() { return min_roll + (random() % range); });

    // sort the vector to ensure a deterministic result
    sort(a.begin(), a.end());

    return a;
}

