def solve(a, k):
    n = len(a)
    if k == 0:
        return sum(a)
    if k == 1:
        return max(a)
    if n == 1:
        return a[0]

    # compute prefix and suffix sums
    prefix_sums = [0] * (n + 1)
    suffix_sums = [0] * (n + 1)
    for i in range(n):
        prefix_sums[i + 1] = prefix_sums[i] + a[i]
        suffix_sums[n - i] = suffix_sums[n - i + 1] + a[i]

    # compute the maximum score
    max_score = 0
    for i in range(n - k + 1):
        for j in range(i + 1, i + k):
            max_score = max(max_score, prefix_sums[i] + suffix_sums[j + 1])

    return max_score

