def solve(n):
   # Initialize the permutation chain with the identity permutation
   permutations = [list(range(1, n+1))]

   # Repeat the following steps until we can't permute the current permutation
   while True:
       # Store the current permutation in the permutations list
       permutations.append(permutations[-1])

       # Find two elements in the current permutation that are not in the same position
       i, j = 0, 0
       while i < n and j < n and i != j:
           i = permutations[-1][j] - 1
           j = permutations[-1][i] - 1

       # Swap these two elements
       permutations[-1][i], permutations[-1][j] = permutations[-1][j], permutations[-1][i]

       # Check if the current permutation can be permuted further
       can_permute = True
       for i in range(n):
           for j in range(i+1, n):
               if permutations[-1][i] == permutations[-1][j]:
                   can_permute = False
                   break
           if not can_permute:
               break

       # If we can't permute the current permutation, break the loop
       if not can_permute:
           break

   # Return the length of the permutation chain
   return len(permutations)

