def solve(n, m):
   # Initialize a 2D table to store the minimum cost for each cell
   dp = [[0] * (m + 1) for _ in range(n + 1)]

   # Base case: If the cell is in the top-left corner, the cost is 0
   dp[1][1] = 0

   # Loop through each cell in the table
   for i in range(1, n + 1):
       for j in range(1, m + 1):
           # If the cell is not in the top-left corner, the cost is the minimum of the costs of the two neighbors
           if i > 1 and j > 1:
               dp[i][j] = min(dp[i - 1][j], dp[i][j - 1])
           # If the cell is in the top-left corner, the cost is the value of the cell
           elif i == 1 and j == 1:
               dp[i][j] = 0
           # If the cell is in the bottom-right corner, the cost is the value of the cell
           elif i == n and j == m:
               dp[i][j] = (i - 1) * m + j

   # Return the minimum cost of reaching the bottom-right corner
   return dp[n][m]
